#include <algorithm>
#include <map>
#include <string>
#include <vector>

std::vector<std::vector<std::string>> groupAnagrams(const std::vector<std::string>& words)
{
    std::map<std::string, std::vector<std::string>> groups{};
    for (const std::string& word : words)
    {
        std::string key{ word };
        std::sort(key.begin(), key.end());
        groups[key].push_back(word);
    }
    std::vector<std::vector<std::string>> result{};
    for (const auto& [key, group] : groups)
    {
        result.push_back(group);
    }
    return result;
}

unitTests:
using Groups = std::vector<std::vector<std::string>>;
TEST("groups anagrams together") { CHECK_EQ(groupAnagrams({ "listen", "google", "silent", "enlist", "cat", "act" }), (Groups{ { "cat", "act" }, { "google" }, { "listen", "silent", "enlist" } })); }
TEST("words with no partner form their own group") { CHECK_EQ(groupAnagrams({ "b", "a" }), (Groups{ { "a" }, { "b" } })); }
TEST("repeated words stay") { CHECK_EQ(groupAnagrams({ "ab", "ba", "ab" }), (Groups{ { "ab", "ba", "ab" } })); CHECK(groupAnagrams({}).empty()); }

